{"path": "plugin-drafts/greeting/src/greet.js", "content": "// Greeting plugin action: greet a person by name.
//
// Exports async run(input, context). The host supplies identity via `context`
// (orgId, pluginId, pluginVersion, actionKey, actor, invocationId, and for tool
// calls profileId, sessionId, workspaceRoot). Identity is never taken from input.

export async function run(input, context) {
  const raw = input && typeof input.name === "string" ? input.name : "";
  const name = raw.trim();

  if (name.length === 0) {
    throw new Error("name must be a non-empty string");
  }

  return {
    message: `Hello, ${name}!`,
    name,
    actionKey: context && context.actionKey ? context.actionKey : "greet",
  };
}
"}

